# Kaggle script kernel (GPU T4): saved-view mutation check on CUDA (Triton path) and Linux CPU, torch 2.14.0.
import base64, os, subprocess, sys
open("saved_view_variants.py", "wb").write(base64.b64decode(""))
subprocess.run(["pip", "-q", "install", "--upgrade", "torch==2.14.0"])
for dev in ("cuda", "cpu"):
    subprocess.run([sys.executable, "saved_view_variants.py"], env=dict(os.environ, TCC_DEVICE=dev))
print("JOB DONE", flush=True)
